#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> pii;
#define rep(i,n) for(ll i=0;i<(ll)(n);i++)
#define all(a)  (a).begin(),(a).end()
#define pb push_back
#define INF 999999999

int main() {
    int n, m;
    while (cin >> n >> m) {
        if (n == 0 && m == 0) break;

        vector<vector<double>> g(n, vector<double>(n));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                cin >> g[i][j];
            }
        }

        vector<double> dp(n, -1); // Reduced to a 1D dp array
        for (int i = 0; i < n; i++) dp[i] = 1.0; // Initialize for step 1

        for (int i = 1; i < m; i++) {
            vector<double> new_dp(n, -1); // Prepare new dp for current step
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    new_dp[j] = max(new_dp[j], dp[k] * g[k][j]);
                }
            }
            dp = new_dp; // Update dp to new_dp for next iteration
        }

        double ans = *max_element(dp.begin(), dp.end());
        printf("%.2lf\n", ans);
    }
}

