typedef long long ll;
typedef pair<int,int> pii;
#define rep(i,n) for(ll i=0;i<(ll)(n);i++)
#define all(a)  (a).begin(),(a).end()
#define pb push_back
#define INF 999999999

int main() {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        vector<double> g(n * n); // Flattening the 2D graph into a 1D array
        for (int i = 0; i < n * n; i++) {
            scanf("%lf", &g[i]);
        }

        vector<double> dp(n, -1);
        fill(dp.begin(), dp.end(), 1.0); // Initialize dp[1] to 1.0 directly

        for (int i = 2; i <= m; i++) {
            vector<double> new_dp(n, -1); // New dp array for current iteration
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    new_dp[j] = max(new_dp[j], dp[k] * g[k * n + j]); // Accessing the 1D array
                }
            }
            dp = move(new_dp); // Move the new dp into the old dp
        }

        double ans = *max_element(dp.begin(), dp.end());
        printf("%.2lf\n", ans);
    }
}

